<?php
declare(strict_types=1);
require_once __DIR__.'/fixtures/PrintifyApiApprovalFixture.php';
use DigiForge\POD\{PrintifyApiReadWorkflow,PrintifyLifecycleWorkflow,PrintifyControlledTransport};
final class PrintifySupportExecutionTest extends WP_UnitTestCase {
 private PrintifyApiApprovalFixture $fixture;
 public static function set_up_before_class():void{parent::set_up_before_class();PrintifyApiApprovalFixture::checked(DigiForge\Database\ProviderConnectionSchema::migrateIfNeeded());}
 protected function setUp():void{parent::setUp();$this->fixture=new PrintifyApiApprovalFixture();$this->fixture->boot();}
 protected function tearDown():void{try{$this->fixture->restore();}finally{parent::tearDown();}}
 private function order():array{$w=new PrintifyApiReadWorkflow();$p=PrintifyApiApprovalFixture::checked($w->prepare('personalized_pod',$this->fixture->integration,'ORDER_READ',['order_id'=>'o1']));$a=$this->fixture->approve($w,$p,'printify-api-read');return PrintifyApiApprovalFixture::checked((new PrintifyControlledTransport(static fn()=>PrintifyApiApprovalFixture::response(['id'=>'o1','status'=>'fulfilled','line_items'=>[['id'=>'l1','product_id'=>'p1','variant_id'=>3,'quantity'=>2,'status'=>'fulfilled']]])))->executeApiRead($p['hash'],$a['hash']));}
 private function input():array{return ['order_id'=>'o1','reason'=>'wrong_design','description'=>'Synthetic wrong side.','line_items'=>[['line_item_id'=>'l1','quantity'=>1]]];}
 private function item(string $type='order_refund'):array{return ['id'=>'s1','order_id'=>'o1','type'=>$type,'status'=>'processing','outcome'=>'unresolved','line_item_ids'=>['l1'],'created_at'=>'2026-08-24 10:00:00+00:00','updated_at'=>'2026-08-24 10:00:00+00:00'];}
 private function dispatch(string $op,array $input,array $response,int $status=200,string $read=''):array{$w=new PrintifyLifecycleWorkflow();$p=PrintifyApiApprovalFixture::checked($w->prepare('personalized_pod',$this->fixture->integration,$op,$input,$read));$a=$this->fixture->approve($w,$p,'printify-lifecycle');$r=PrintifyApiApprovalFixture::checked((new PrintifyControlledTransport(static fn()=>PrintifyApiApprovalFixture::response($response,$status)))->executeLifecycle($p['hash'],$a['hash']));self::assertSame('SUCCEEDED',$r['record']['status']);return $r;}
 public function testAllSupportOperationsUseReviewedOrderScopeWithoutGuaranteeingRefunds():void{
  $read=$this->order();$refund=$this->dispatch('SUPPORT_REFUND',$this->input(),$this->item(),201,$read['hash']);self::assertFalse($refund['record']['data']['refund_guaranteed']);
  $this->dispatch('SUPPORT_REPRINT',$this->input(),$this->item('order_reprint'),201,$read['hash']);$list=$this->dispatch('SUPPORT_LIST',['order_id'=>'o1'],['data'=>[$this->item()]]);$this->dispatch('SUPPORT_DETAIL',['order_id'=>'o1','support_request_id'=>'s1'],['data'=>$this->item()]);
  $w=new PrintifyLifecycleWorkflow();$resolved=PrintifyApiApprovalFixture::checked($w->reconcile($refund['hash'],$list['hash']));self::assertSame('CONFIRMED_BY_READBACK',$resolved['record']['disposition']);
  $address=['order_id'=>'o1','first_name'=>'Synthetic','last_name'=>'Recipient','address1'=>'Private Fixture Street','city'=>'Fixture','country'=>'US','zip'=>'90210'];$r=$this->dispatch('SUPPORT_ADDRESS_CHANGE',$address,['resolution'=>'updated_directly','order_id'=>'o1','address_to'=>array_diff_key($address,['order_id'=>true])],200,$read['hash']);self::assertArrayNotHasKey('address_to',$r['record']['data']);self::assertStringNotContainsString('Private Fixture Street',get_option('digiforge_pfy_lifecycle_plan_'.$r['record']['plan_hash']));
 }
 public function testUnknownSupportOutcomeCannotBeReauthorizedOrFalselyCorrelated():void{
  $w=new PrintifyLifecycleWorkflow();$read=$this->order();$p=PrintifyApiApprovalFixture::checked($w->prepare('personalized_pod',$this->fixture->integration,'SUPPORT_REFUND',$this->input(),$read['hash']));$a=$this->fixture->approve($w,$p,'printify-lifecycle');$calls=0;$t=new PrintifyControlledTransport(static function()use(&$calls){$calls++;return new WP_Error('isolated_timeout');});$r=PrintifyApiApprovalFixture::checked($t->executeLifecycle($p['hash'],$a['hash']));self::assertSame('UNKNOWN',$r['record']['status']);self::assertWPError($t->executeLifecycle($p['hash'],$a['hash']));
  $p2=PrintifyApiApprovalFixture::checked($w->prepare('personalized_pod',$this->fixture->integration,'SUPPORT_REFUND',$this->input(),$read['hash']));$a2=$this->fixture->approve($w,$p2,'printify-lifecycle');self::assertWPError($t->executeLifecycle($p2['hash'],$a2['hash']));self::assertSame(1,$calls);
  $list=$this->dispatch('SUPPORT_LIST',['order_id'=>'o1'],['data'=>[$this->item()]]);$obs=PrintifyApiApprovalFixture::checked($w->reconcile($r['hash'],$list['hash']));self::assertSame('UNKNOWN_REQUIRES_PROVIDER_CORRELATION',$obs['record']['disposition']);self::assertFalse($obs['record']['retry_authorized']);
 }
 public function testMissingForeignAndUnreviewedEvidenceNeverDispatches():void{
  $w=new PrintifyLifecycleWorkflow();self::assertWPError($w->prepare('personalized_pod',$this->fixture->integration,'SUPPORT_REFUND',$this->input()));$read=$this->order();$bad=$this->input();$bad['line_items'][0]['line_item_id']='foreign';self::assertWPError($w->prepare('personalized_pod',$this->fixture->integration,'SUPPORT_REFUND',$bad,$read['hash']));$bad=$this->input();$bad['line_items'][0]['quantity']=3;self::assertWPError($w->prepare('personalized_pod',$this->fixture->integration,'SUPPORT_REFUND',$bad,$read['hash']));self::assertWPError($w->prepare('standard_pod',$this->fixture->integration,'SUPPORT_LIST',['order_id'=>'o1']));
  $p=PrintifyApiApprovalFixture::checked($w->prepare('personalized_pod',$this->fixture->integration,'SUPPORT_LIST',['order_id'=>'o1']));self::assertWPError($w->authorize($p['hash']));$a=$this->fixture->approve($w,$p,'printify-lifecycle');wp_get_current_user()->add_cap('manage_digiforge_orders',false);try{self::assertWPError($w->prepare('personalized_pod',$this->fixture->integration,'SUPPORT_LIST',['order_id'=>'o1']));}finally{wp_get_current_user()->add_cap('manage_digiforge_orders',true);}$this->fixture->setting('stop_all',true);$calls=0;self::assertWPError((new PrintifyControlledTransport(static function()use(&$calls){$calls++;}))->executeLifecycle($p['hash'],$a['hash']));self::assertSame(0,$calls);
 }
}
